/* logic.c - decisions only, no framework headers, linked into the test */
bool order_total_ok(const order_t *order, int limit);

/* shell.c - the framework calls this: read, delegate, apply */
static void on_submit_clicked(widget_ctx_t *w) {      /* toolkit callback */
    order_t order;
    widget_read_order(w, &order);
    if (order_total_ok(&order, widget_credit_limit(w)))
        widget_show_confirmation(w, order.total);
}
